const readKey="inviata-admin-read-orders",authKey="inviata-admin-auth",pinnedKey="inviata-admin-pinned-orders",fixedImageSlotCount=2;const WEBSITE_PIPELINE_CONFIG={workerUrl:"https://order-backend.inviata-orders-in.workers.dev/upload",websiteBaseUrl:"https://inviata.in",alterationBaseUrl:"https://inviata.in/alter",repoName:"Invitations",branch:"main",pollIntervalMs:2500,pollTimeoutMs:90000};const WEBSITE_UPLOAD_FIELDS=[{key:"couplePhoto",label:"Couple Photo",required:true,multiple:false,accept:"image/*",prefix:"cp",desc:"Primary couple image for hero, OG and cover fallbacks."},{key:"familyPhoto",label:"Family Photo",required:false,multiple:false,accept:"image/*",prefix:"fp",desc:"Optional family image for secondary full-width placement."},{key:"galleryImages",label:"Gallery Images",required:true,multiple:true,accept:"image/*",prefix:"g",desc:"Gallery photos used across the invitation body."},{key:"webpAssets",label:"WebP Assets",required:true,multiple:true,accept:".webp,image/webp",prefix:"w",desc:"Final designed invitation assets uploaded as WEBP files."},{key:"otherAssets",label:"Other Assets",required:false,multiple:true,accept:"image/*,audio/*,.mp3,.wav,.m4a,.aac,.zip,.pdf",prefix:"a",desc:"Optional supporting assets like audio or extra files."}];const WEBSITE_GENERATION_STEPS=["Uploading Images...","Preparing Template...","Replacing Placeholders...","Generating HTML...","Uploading index.html...","Publishing Website...","Website Ready."];
