const el={login:document.getElementById("loginScreen"),dash:document.getElementById("dash"),loginForm:document.getElementById("loginForm"),username:document.getElementById("username"),password:document.getElementById("password"),userField:document.getElementById("userField"),passField:document.getElementById("passField"),userError:document.getElementById("userError"),passError:document.getElementById("passError"),formError:document.getElementById("formError"),logoutBtn:document.getElementById("logoutBtn"),search:document.getElementById("searchInput"),status:document.getElementById("statusFilter"),template:document.getElementById("templateFilter"),date:document.getElementById("dateFilter"),orders:document.getElementById("orders"),workspace:document.getElementById("workspace"),orderModal:document.getElementById("orderModal"),orderModalBody:document.getElementById("orderModalBody"),closeOrderModal:document.getElementById("closeOrderModal"),imageModal:document.getElementById("imageModal"),imageModalTitle:document.getElementById("imageModalTitle"),imageModalBody:document.getElementById("imageModalBody"),closeImageModal:document.getElementById("closeImageModal"),clientModal:document.getElementById("clientModal"),clientModalBody:document.getElementById("clientModalBody"),closeClientModal:document.getElementById("closeClientModal"),generationModal:document.getElementById("generationModal"),generationModalBody:document.getElementById("generationModalBody"),closeGenerationModal:document.getElementById("closeGenerationModal")};
init();
function init(){bind();hydrateFilters();render();if(state.isAuth)startRealtime()}
function bind(){el.loginForm.addEventListener("submit",onLogin);el.logoutBtn.addEventListener("click",onLogout);el.search.addEventListener("input",e=>{state.filters.search=e.target.value.trim().toLowerCase();applyFilters()});el.status.addEventListener("change",e=>{state.filters.status=e.target.value;applyFilters()});el.template.addEventListener("change",e=>{state.filters.template=e.target.value;applyFilters()});el.date.addEventListener("change",e=>{state.filters.date=e.target.value;applyFilters()});el.orders.addEventListener("click",onOrdersClick);el.workspace.addEventListener("click",onWorkspaceClick);el.workspace.addEventListener("change",onWorkspaceChange);el.closeOrderModal.addEventListener("click",closeOrderModal);el.closeImageModal.addEventListener("click",closeImageModal);el.closeClientModal.addEventListener("click",closeClientModal);el.closeGenerationModal.addEventListener("click",closeGenerationModal);el.orderModal.addEventListener("click",e=>{if(e.target===el.orderModal)closeOrderModal()});el.imageModal.addEventListener("click",e=>{if(e.target===el.imageModal)closeImageModal()});el.clientModal.addEventListener("click",e=>{if(e.target===el.clientModal)closeClientModal()});el.generationModal.addEventListener("click",e=>{if(e.target===el.generationModal)closeGenerationModal()});el.generationModalBody.addEventListener("click",onWorkspaceClick);el.generationModalBody.addEventListener("change",onWorkspaceChange);el.orderModalBody.addEventListener("click",e=>{const p=e.target.closest('[data-preview-src]');if(p){state.modal.image=true;state.modal.src=p.dataset.previewSrc;state.modal.title=p.dataset.previewTitle||'Photo Preview';renderModals()}});document.addEventListener("click",e=>{if(state.menuOpen&&!e.target.closest('.order-menu-wrap')){state.menuOpen=null;renderOrders()}});document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeOrderModal();closeImageModal();closeClientModal();closeGenerationModal();if(state.menuOpen){state.menuOpen=null;renderOrders()}}})}
function hydrateFilters(){el.status.innerHTML=`<option value="all">All Status</option><option value="waiting">Waiting</option><option value="approved">Approved</option><option value="on-hold">On Hold</option><option value="rejected">Rejected</option><option value="completed">Completed</option>`;el.template.innerHTML=`<option value="all">All Template</option>`;el.date.value=state.filters.date||''}
function onLogin(e){e.preventDefault();clearLoginErrors();const u=el.username.value.trim(),p=el.password.value;let ok=true;if(!u){el.userField.classList.add("bad");el.userError.textContent="Please enter username.";ok=false}if(!p){el.passField.classList.add("bad");el.passError.textContent="Please enter password.";ok=false}if(!ok)return;if(u!==ADMIN.username||p!==ADMIN.password){el.formError.textContent="Incorrect username or password.";return}state.isAuth=true;sessionStorage.setItem(authKey,"true");el.password.value="";render();startRealtime()}
function onLogout(){if(state.unsub)state.unsub();state.unsub=null;state.isAuth=false;state.orders=[];state.filtered=[];state.selected=null;sessionStorage.removeItem(authKey);render()}
function clearLoginErrors(){el.userField.classList.remove("bad");el.passField.classList.remove("bad");el.userError.textContent="";el.passError.textContent="";el.formError.textContent=""}
function render(){el.login.classList.toggle("hidden",state.isAuth);el.dash.classList.toggle("hidden",!state.isAuth);if(!state.isAuth)return;renderTemplateFilter();renderOrders();renderWorkspace();renderModals()}
function startRealtime(){if(state.unsub)state.unsub();state.unsub=onSnapshot(collection(db,"orders"),snap=>{state.orders=snap.docs.map(s=>normalizeOrder(s)).sort((a,b)=>toMillis(b.createdAt)-toMillis(a.createdAt));applyFilters()},err=>{console.error(err);el.workspace.innerHTML=`<section class="blank"><div><h2>Connection issue</h2><p>${escapeHtml(readableError(err))}</p></div></section>`})}
function normalizeOrder(s){const d=s.data()||{};return{docId:s.id,orderId:d.orderId||s.id,status:d.status||"Waiting",templateId:d.templateId||"Unknown",createdAt:d.createdAt||null,customer:d.customer||{},bride:d.bride||{},groom:d.groom||{},events:Array.isArray(d.events)?d.events:[],closing:d.closing||{},bridePrefixSuffix:d.bridePrefixSuffix||null,groomPrefixSuffix:d.groomPrefixSuffix||null,religiousPreference:d.religiousPreference||"",caricatures:d.caricatures||null,customization:d.customization||null,websiteGeneration:d.websiteGeneration||{},raw:d}}
function applyFilters(){const q=state.filters.search;state.filtered=state.orders.filter(o=>{const searchOK=!q||[o.orderId,o.bride?.name,o.groom?.name].some(v=>String(v||"").toLowerCase().includes(q));const statusOK=state.filters.status==="all"||normalizeStatus(o.status)===state.filters.status;const templateOK=state.filters.template==="all"||o.templateId===state.filters.template;const dateOK=!state.filters.date||toDateFilterValue(o.createdAt)===state.filters.date;return searchOK&&statusOK&&templateOK&&dateOK}).sort(compareOrders);if(state.selected&&!state.filtered.some(o=>o.docId===state.selected))state.selected=null;render()}
function renderTemplateFilter(){const arr=[...new Set(state.orders.map(o=>o.templateId).filter(Boolean))].sort();const cur=state.filters.template;el.template.innerHTML=`<option value="all">All Template</option>${arr.map(v=>`<option value="${escapeHtml(v)}" ${cur===v?"selected":""}>${escapeHtml(v)}</option>`).join("")}`;if(!arr.includes(cur)&&cur!=="all")state.filters.template="all";el.template.value=state.filters.template;el.status.value=state.filters.status;el.date.value=state.filters.date||""}
function renderOrders(){if(!state.filtered.length){el.orders.innerHTML=`<section class="blank" style="min-height:200px;"><div><h2 style="font-size:1.4rem;">No orders</h2><p>Search ya filter change karke dekhiye.</p></div></section>`;return}el.orders.innerHTML=state.filtered.map(o=>{const read=!!state.read[o.docId];const pinned=!!state.pinned[o.docId];const busy=!!state.busy[o.docId];return`<article class="order ${read?"read":"unread"} ${state.selected===o.docId?"active":""}" data-order="${escapeHtml(o.docId)}"><div class="order-top"><div class="order-top-main"><div class="oid">${escapeHtml(o.orderId)}</div><div class="oname">${escapeHtml(o.bride?.name||"Bride")} · ${escapeHtml(o.groom?.name||"Groom")}</div></div><div class="order-status-row order-menu-wrap"><span class="badge ${normalizeStatus(o.status)}">${escapeHtml(o.status)}</span><button class="menu-dot" type="button" aria-label="Order actions" data-menu-toggle="${escapeHtml(o.docId)}" ${busy?"disabled":""}>⋮</button>${state.menuOpen===o.docId?`<div class="menu-panel"><button class="menu-item" type="button" data-pin-order="${escapeHtml(o.docId)}">${pinned?"Unpin Order":"Pin Order"}</button><button class="menu-item danger" type="button" data-delete-order="${escapeHtml(o.docId)}">Delete Order</button><button class="menu-item" type="button" data-client-order="${escapeHtml(o.docId)}">Show Client Information</button></div>`:""}</div></div><div class="ometa"><span class="badge">${escapeHtml(o.templateId)}</span><span class="tiny">${escapeHtml(formatDate(o.createdAt))}</span>${pinned?`<span class="pin-mark">Pinned</span>`:""}</div></article>`}).join("")}
function onOrdersClick(e){const toggle=e.target.closest('[data-menu-toggle]');if(toggle){const id=toggle.dataset.menuToggle;state.menuOpen=state.menuOpen===id?null:id;renderOrders();return}const pin=e.target.closest('[data-pin-order]');if(pin){state.menuOpen=null;togglePinned(pin.dataset.pinOrder);return}const client=e.target.closest('[data-client-order]');if(client){state.menuOpen=null;state.modal.client=true;state.modal.clientId=client.dataset.clientOrder;renderOrders();renderModals();return}const del=e.target.closest('[data-delete-order]');if(del){state.menuOpen=null;deleteOrder(del.dataset.deleteOrder);return}const card=e.target.closest('[data-order]');if(card){state.selected=card.dataset.order;markRead(card.dataset.order);state.menuOpen=null;renderOrders();renderWorkspace();renderModals()}}
function togglePinned(id){if(state.pinned[id])delete state.pinned[id];else state.pinned[id]=true;localStorage.setItem(pinnedKey,JSON.stringify(state.pinned));applyFilters()}
async function deleteOrder(id){try{if(!confirm('Delete this order from Firestore only?'))return;state.busy[id]=true;renderOrders();await deleteDoc(doc(db,'orders',id));if(state.selected===id)state.selected=null;state.modal.client=false;state.modal.clientId=null}catch(err){console.error(err);alert(readableError(err))}finally{delete state.busy[id];state.menuOpen=null;renderOrders();renderWorkspace();renderModals()}}
function compareOrders(a,b){const pinDiff=Number(!!state.pinned[b.docId])-Number(!!state.pinned[a.docId]);if(pinDiff)return pinDiff;return toMillis(b.createdAt)-toMillis(a.createdAt)}
function getOrderById(id){return state.orders.find(v=>v.docId===id)||null}
function renderWorkspace(){const order=getSelectedOrder();if(!order){el.workspace.innerHTML=`<section class="blank"><div><h2>Blank workspace</h2><p>Kisi bhi order par click karte hi approval screen aur uske baad template workspace yahin khulega.</p></div></section>`;return}const st=normalizeStatus(order.status);if(["waiting","rejected","on-hold"].includes(st)){el.workspace.innerHTML=renderApproval(order);return}const key=resolveTemplateKey(order.templateId);const renderer=RENDERERS[key]||RENDERERS[TEMPLATE_LIBRARY.defaultTemplateKey];el.workspace.innerHTML=renderer(order)}
const RENDERERS={template1:renderTemplate1};
function renderApproval(order){const st=normalizeStatus(order.status);return`<section class="approval glass"><div class="head"><div><h2>${escapeHtml(order.orderId)} · ${escapeHtml(order.templateId)}</h2></div><div class="action-row"><button class="ghost" data-view-details="${escapeHtml(order.docId)}">View Order Details</button></div></div><div class="approval-meta"><span class="badge ${st}">${escapeHtml(order.status)}</span><span class="badge">${escapeHtml(formatDate(order.createdAt))}</span></div><div class="quick"><div class="q"><div class="ql">Bride</div><div class="qv">${escapeHtml(order.bride?.name||"—")}</div></div><div class="q"><div class="ql">Groom</div><div class="qv">${escapeHtml(order.groom?.name||"—")}</div></div><div class="q"><div class="ql">Events</div><div class="qv">${order.events.length}</div></div><div class="q"><div class="ql">Name Order</div><div class="qv">${escapeHtml(order.customer?.nameOrder||"—")}</div></div></div><div class="action-row"><button class="btn" data-approve="${escapeHtml(order.docId)}" ${state.busy[order.docId]?"disabled":""}>${state.busy[order.docId]?"Approving...":"Approve"}</button><button class="ghost" data-hold="${escapeHtml(order.docId)}">Hold Order</button><button class="ghost" data-reject="${escapeHtml(order.docId)}">Reject Order</button></div>${renderWebsiteGenerationSection(order)}</section>`}
function renderTemplate1(order){const ordered=getOrderedPeople(order);const initials=getOrderedInitials(order);const opening=`Generate exactly the same image in WEBP format. Change initials to ${initials}. Return final WEBP image only.`;const formal=`${ordered[0].name||""}
${ordered[0].parents||""}${ordered[0].grandparents?`
${ordered[0].grandparents}`:""}

with

${ordered[1].name||""}
${ordered[1].parents||""}${ordered[1].grandparents?`
${ordered[1].grandparents}`:""}`.trim();const cards=[renderPromptCard(order,'opening',opening),renderPromptCard(order,'formal',formal),...order.events.map((ev,i)=>renderPromptCard(order,`event-${i}`,formatEventInfo(ev)))].join('');const slots=getManualImageSlots(order);return`<section class="workspace"><div class="head"><div><h2>${escapeHtml(order.orderId)} · ${escapeHtml(order.templateId)}</h2></div><div class="action-row"><button class="ghost" data-view-details="${escapeHtml(order.docId)}">View Order Details</button></div></div><section class="strip glass"><div class="thumb-row">${slots.map(slot=>renderManualSlot(order,slot)).join('')}${renderAddMoreImagesCard(order)}</div></section>${renderWebsiteGenerationSection(order)}<section class="prompt-strip glass"><div class="prompt-row">${cards}</div></section></section>`}
function getManualImageSlots(order){state.manualRefs[order.docId]??={};const fixed=Array.from({length:fixedImageSlotCount},(_,idx)=>{const index=idx+1;return{index,fixed:true,upload:state.manualRefs[order.docId][index]||null}});const extra=Object.keys(state.manualRefs[order.docId]).map(Number).filter(v=>v>fixedImageSlotCount).sort((a,b)=>a-b).map(index=>({index,fixed:false,upload:state.manualRefs[order.docId][index]||null}));return[...fixed,...extra]}
function renderManualSlot(order,slot){const inputId=safeId(`manual-ref-${order.docId}-${slot.index}`);const title=slot.fixed?`Fixed Slot ${slot.index}`:`Image ${slot.index-fixedImageSlotCount}`;if(slot.upload)return`<article class="thumb-card ${slot.fixed?'blank-fixed':''}"><input id="${inputId}" class="hidden" type="file" accept="image/*" data-manual-ref="${escapeHtml(order.docId)}" data-slot-index="${slot.index}" /><button class="thumb-btn" type="button" data-preview-src="${escapeHtml(slot.upload.url)}" data-preview-title="${escapeHtml(title)}"><img src="${escapeHtml(slot.upload.url)}" alt="${escapeHtml(title)}" /></button><label class="mini" for="${inputId}" style="display:inline-flex;align-items:center;justify-content:center;">${slot.fixed?'Upload / Replace':'Replace'}</label><div class="thumb-name">${escapeHtml(title)}</div></article>`;return`<article class="thumb-card add-thumb ${slot.fixed?'blank-fixed':''}"><label for="${inputId}"><input id="${inputId}" class="hidden" type="file" accept="image/*" data-manual-ref="${escapeHtml(order.docId)}" data-slot-index="${slot.index}" /><div class="add-box ${slot.fixed?'fixed-slot':''}">${slot.fixed?`<span>Fixed Slot ${slot.index}</span><small>Upload Image</small>`:'Add Image'}</div><div class="thumb-name">${escapeHtml(title)}</div></label></article>`}
function renderAddMoreImagesCard(order){const inputId=safeId(`add-more-images-${order.docId}`);return`<article class="thumb-card add-thumb"><label for="${inputId}"><input id="${inputId}" class="hidden" type="file" accept="image/*" multiple data-add-more-images="${escapeHtml(order.docId)}" /><div class="add-box">Add More Images</div><div class="thumb-name">Unlimited Extra Images</div></label></article>`}
function renderWebsiteGenerationSection(order){const ui=getWebsiteUi(order.docId),data=getWebsiteGenerationData(order),missing=getMissingWebsiteUploads(order);return`<section class="website-gen"><div class="website-gen-head"><div><h3>Website Generation</h3></div><div class="website-gen-note">Folder: <strong>${escapeHtml(data.folderSlug||buildFolderSlug(order))}</strong></div></div><div class="website-gen-grid">${getRequiredWebsiteSlots(order).map(slot=>renderExistingTabSummary(order,slot)).join('')}</div><div class="website-gen-footer"><div class="website-gen-note">${missing.length?`Required uploads pending: ${escapeHtml(missing.map(v=>v.label).join(', '))}`:'All required uploads are complete. You can start generation.'}</div><div class="action-row"><button class="btn" type="button" data-open-generate="${escapeHtml(order.docId)}">${data.websiteUrl?'Regenerate Website':'Generate Website'}</button></div></div>${renderWebsiteFlow(order)}`}
function renderWebsiteUploadCard(order,field){const ui=getWebsiteUi(order.docId),data=getWebsiteGenerationData(order),uploaded=(data.assets[field.key]||[]),drafts=ui.drafts[field.key]||[],slot=ui.uploads[field.key]||{},klass=['asset-card'];if(field.required&&!uploaded.length)klass.push('missing');if(slot.busy)klass.push('busy');if(uploaded.length&&!slot.busy)klass.push('done');return`<article class="${klass.join(' ')}"><div class="asset-card-top"><div class="asset-card-title">${escapeHtml(field.label)}</div><span class="asset-badge ${uploaded.length?'done':field.required?'required':''}">${uploaded.length?`${uploaded.length} uploaded`:field.required?'Required':'Optional'}</span></div><div class="asset-card-desc">${escapeHtml(field.desc)}</div><input id="${safeId(`website-${order.docId}-${field.key}`)}" class="hidden" type="file" accept="${escapeHtml(field.accept)}" ${field.multiple?'multiple':''} data-website-files="${escapeHtml(order.docId)}" data-asset-key="${escapeHtml(field.key)}" /><div class="asset-actions"><label class="mini" for="${safeId(`website-${order.docId}-${field.key}`)}">Choose File</label><button class="mini" type="button" data-upload-website-assets="${escapeHtml(order.docId)}" data-asset-key="${escapeHtml(field.key)}" ${slot.busy?'disabled':''}>${slot.busy?'Uploading...':'Upload'}</button></div><div class="asset-file-pill">${drafts.length?escapeHtml(drafts.map(v=>v.name).join(', ')):'No file selected'}</div><div class="asset-count">GitHub URLs stored: ${uploaded.length}</div>${slot.busy?`<div class="progress-track"><div class="progress-bar" style="width:${Math.max(4,slot.progress||4)}%"></div></div>`:''}<div class="asset-status">${escapeHtml(slot.error||slot.success||(drafts.length?'Ready to upload selected files.':'Choose files and upload to save raw URLs.'))}</div></article>`}
function renderWebsiteFlow(order){const ui=getWebsiteUi(order.docId),flow=ui.flow,data=getWebsiteGenerationData(order);if(!flow.busy&&!flow.error&&!flow.success&&!data.websiteUrl)return'';const steps=WEBSITE_GENERATION_STEPS.map((label,i)=>{const c=i<flow.step?'done':i===flow.step?(flow.error?'error':'active'):'';return`<div class="flow-step ${c}">${escapeHtml(label)}</div>`}).join('');return`<div class="website-flow"><div class="flow-steps">${steps}</div>${flow.busy?`<div class="website-gen-note">${escapeHtml(flow.message||WEBSITE_GENERATION_STEPS[flow.step]||'Processing...')}</div>`:''}${flow.error?`<div class="setup-warn" style="border-color:#f1c4c4;background:#fff7f7;color:#a14b4b;">${escapeHtml(flow.error)}</div>`:''}${data.websiteUrl?`<div class="website-live-card"><div class="website-live-title">✅ Website ${flow.success?'Generated':'Live'}</div><div class="live-meta">${escapeHtml(flow.success||('Last published: '+formatIso(data.lastPublishedAt)))}</div><div class="link-box">${escapeHtml(data.websiteUrl)}</div><div class="link-actions"><button class="ghost" type="button" data-open-url="${escapeHtml(data.websiteUrl)}">Open Website</button><button class="ghost" type="button" data-copy-text="${escapeHtml(data.websiteUrl)}">Copy URL</button><button class="ghost" type="button" data-open-generate="${escapeHtml(order.docId)}">Regenerate Website</button></div><div class="website-gen-note">Customer Alteration Link</div><div class="link-box">${escapeHtml(data.alterationUrl||composeAlterationUrl(data.folderSlug||buildFolderSlug(order)))}</div><div class="link-actions"><button class="ghost" type="button" data-copy-text="${escapeHtml(data.alterationUrl||composeAlterationUrl(data.folderSlug||buildFolderSlug(order)))}">Copy Alteration Link</button><button class="ghost" type="button" data-open-url="${escapeHtml(data.alterationUrl||composeAlterationUrl(data.folderSlug||buildFolderSlug(order)))}">Open Link</button></div></div>`:''}</div>`}
function renderGenerationModal(order){const data=getWebsiteGenerationData(order),missing=getMissingWebsiteUploads(order);const ui=getWebsiteUi(order.docId);const musicDraft=ui.musicDraft||{};const musicUpload=ui.musicUpload||{busy:false,progress:0,error:'',success:''};const clipDraft=ui.musicClip||{};const clipStart=clipDraft.start??(data.musicStartSec??'');const clipEnd=clipDraft.end??(data.musicEndSec??'');return`<div class="grid"><div class="website-gen-note">Confirm once all required images from the existing dynamic tabs are uploaded. The system will prepare the template, replace placeholders, generate <strong>index.html</strong>, upload it to the same customer folder, wait for publish confirmation, and then surface the live website URL plus alteration link.</div><div class="card"><div class="k">Customer folder</div><div class="v">${escapeHtml(data.folderSlug||buildFolderSlug(order))}</div></div><div class="card"><div class="k">Status</div><div class="v">${missing.length?`Missing: ${escapeHtml(missing.map(v=>v.label).join(', '))}`:'All required uploads complete'}</div></div><div class="card" style="flex-direction:column;gap:10px;"><div class="k">Music</div><label style="display:flex;align-items:center;gap:6px;cursor:pointer;"><input type="radio" name="musicMode-${escapeHtml(order.docId)}" data-music-mode="${escapeHtml(order.docId)}" value="default" ${(!ui.musicMode||ui.musicMode==="default")?"checked":""}> Use Default Song</label><label style="display:flex;align-items:center;gap:6px;cursor:pointer;"><input type="radio" name="musicMode-${escapeHtml(order.docId)}" data-music-mode="${escapeHtml(order.docId)}" value="upload" ${ui.musicMode==="upload"?"checked":""}> Upload MP3</label>${ui.musicMode==="upload"?`<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:4px;"><input type="file" accept=".mp3,audio/mpeg" data-music-file="${escapeHtml(order.docId)}" style="flex:1;min-width:0;"><button class="mini" type="button" data-upload-music="${escapeHtml(order.docId)}" ${musicDraft.file&&!musicUpload.busy?"":"disabled"}>${musicUpload.busy?"Uploading...":"Upload MP3"}</button></div>${musicUpload.busy?`<div class="progress-track"><div class="progress-bar" style="width:${Math.max(4,musicUpload.progress||4)}%"></div></div>`:""}${musicUpload.error?`<div class="asset-status" style="color:red">${escapeHtml(musicUpload.error)}</div>`:""}${musicUpload.success?`<div class="asset-status" style="color:green">${escapeHtml(musicUpload.success)}</div>`:""}`:""}<label style="display:flex;align-items:center;gap:6px;cursor:pointer;"><input type="radio" name="musicMode-${escapeHtml(order.docId)}" data-music-mode="${escapeHtml(order.docId)}" value="url" ${ui.musicMode==="url"?"checked":""}> Paste Music URL</label>${ui.musicMode==="url"?`<div style="display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin-top:4px;"><input type="text" placeholder="https://..." data-music-url-input="${escapeHtml(order.docId)}" value="${escapeHtml(data.assets.musicUrl||"")}" style="flex:1;min-width:0;"><button class="mini" type="button" data-save-music-url="${escapeHtml(order.docId)}">Save URL</button></div>${data.assets.musicUrl?`<div class="asset-status" style="color:green">Saved: ${escapeHtml(data.assets.musicUrl)}</div>`:""}`:""}${ui.musicMode&&ui.musicMode!=="default"?`<div style="display:grid;gap:8px;margin-top:4px;padding:10px;border:1px solid var(--line);border-radius:10px;background:#fafcff;"><div class="k">Song Clip</div><div style="display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px;"><input type="text" data-music-start="${escapeHtml(order.docId)}" value="${escapeHtml(String(clipStart))}" placeholder="Start: 16 / 0:16 / 0.27 min" style="width:100%;padding:8px 12px;height:36px;border-radius:8px;border:1px solid var(--line);outline:none;background:#fff;color:var(--text);font-size:.88rem;"><input type="text" data-music-end="${escapeHtml(order.docId)}" value="${escapeHtml(String(clipEnd))}" placeholder="End: 72 / 1:12 / 1.2 min" style="width:100%;padding:8px 12px;height:36px;border-radius:8px;border:1px solid var(--line);outline:none;background:#fff;color:var(--text);font-size:.88rem;"></div><div class="asset-status">Only this selected section will play. Example: start 16 and end 1:12 will loop that section continuously while the website is open.</div></div>`:""}</div><div class="action-row"><button class="btn" type="button" data-confirm-generate="${escapeHtml(order.docId)}">${missing.length?'Check Missing Uploads':'Generate Website'}</button><button class="ghost" type="button" data-cancel-generate="1">Cancel</button></div></div>`}
function getWebsiteUi(orderId){state.websiteFlow[orderId]??={drafts:{},uploads:{},flow:{busy:false,step:0,message:'',error:'',success:''}};return state.websiteFlow[orderId]}
function getWebsiteGenerationData(order){const base={assets:{promptSlots:{}},folderSlug:'',websiteUrl:'',alterationUrl:'',history:[],lastPublishedAt:''};const raw=order?.websiteGeneration||{};const out={...base,...raw,assets:{...base.assets,...(raw.assets||{})}};out.assets.promptSlots=out.assets.promptSlots&&typeof out.assets.promptSlots==='object'&&!Array.isArray(out.assets.promptSlots)?out.assets.promptSlots:{};return out}
function getRequiredWebsiteSlots(order){const base=[{key:'opening',label:'Envelope / First Interface Image',prefix:'t1'},{key:'formal',label:'Bride, Groom and Parents Details Image',prefix:'t2'}];const eventSlots=(order.events||[]).map((ev,i)=>({key:`event-${i}`,label:`${ev?.name||`Event ${i+1}`} Image`,prefix:`e${i+1}`}));return[...base,...eventSlots]}
function getMissingWebsiteUploads(order){const data=getWebsiteGenerationData(order);return getRequiredWebsiteSlots(order).filter(slot=>!assetUrl(data.assets.promptSlots?.[slot.key]||''))}
function isWorkerConfigured(){return !!(WEBSITE_PIPELINE_CONFIG.workerUrl&&String(WEBSITE_PIPELINE_CONFIG.workerUrl).startsWith('http'))}
function renderExistingTabSummary(order,slot){const data=getWebsiteGenerationData(order),ui=getWebsiteUi(order.docId),asset=data.assets.promptSlots?.[slot.key]||null,status=ui.uploads[slot.key]||{},done=!!assetUrl(asset),klass=['asset-card'];if(!done)klass.push('missing');if(status.busy)klass.push('busy');if(done&&!status.busy)klass.push('done');return`<article class="${klass.join(' ')}"><div class="asset-card-top"><div class="asset-card-title">${escapeHtml(slot.label)}</div><span class="asset-badge ${done?'done':'required'}">${done?'Uploaded':'Required'}</span></div>${status.busy?`<div class="progress-track"><div class="progress-bar" style="width:${Math.max(4,status.progress||4)}%"></div></div>`:''}<div class="asset-status">${escapeHtml(status.error||status.success||(done?'GitHub raw URL stored and ready for generation.':'Upload this image from the existing tab above.'))}</div>${done?`<div class="asset-file-pill">${escapeHtml(asset.name||asset.fileName||slot.label)}</div>`:''}</article>`}
function getPromptUploadLabel(order,slot){const map=Object.fromEntries(getRequiredWebsiteSlots(order).map(item=>[item.key,item.label]));return map[slot]||slot}
function getPromptUploadPrefix(order,slot){const map=Object.fromEntries(getRequiredWebsiteSlots(order).map(item=>[item.key,item.prefix]));return map[slot]||'img'}
function renderPromptCard(order,slot,text){const up=state.uploads[order.docId]?.[slot];const id=safeId(`upload-${order.docId}-${slot}`);const ui=getWebsiteUi(order.docId);const status=ui.uploads[slot]||{};const title=getPromptUploadLabel(order,slot);const uploadedAsset=getWebsiteGenerationData(order).assets.promptSlots?.[slot]||null;const selectedName=up?.name||'';const hasSelected=!!up?.file;return`<article class="prompt-card"><div class="k" style="margin-bottom:4px;">${escapeHtml(title)}</div><div class="prompt">${escapeHtml(text||'—')}</div><div class="upload"><input id="${id}" class="hidden" type="file" accept=".webp,image/webp" data-order-upload="${escapeHtml(order.docId)}" data-slot="${escapeHtml(slot)}" /><div class="asset-actions" style="padding:10px 10px 0;gap:10px;"><label class="mini" for="${id}">${uploadedAsset?'Choose New WEBP':'Choose WEBP'}</label><button class="mini" type="button" data-upload-prompt-slot="${escapeHtml(order.docId)}" data-slot="${escapeHtml(slot)}" ${hasSelected&&!status.busy?'':'disabled'}>${status.busy?'Uploading...':'Upload'}</button></div><div class="upload-inner" style="margin-top:10px;">${selectedName?`<div class="upload-file">${escapeHtml(selectedName)}</div>`:uploadedAsset?`<div class="upload-file">${escapeHtml(uploadedAsset.name||title)}</div>`:`<div class="upload-file">No file selected</div>`}${up?.url?`<img class="upload-preview" src="${escapeHtml(up.url)}" alt="preview" />`:''}</div>${status.busy?`<div class="progress-track" style="margin:0 10px 10px;"><div class="progress-bar" style="width:${Math.max(8,status.progress||8)}%"></div></div>`:''}<div class="asset-status" style="padding:0 10px 10px;">${escapeHtml(status.error||status.success||(hasSelected?'Ready to upload selected WEBP.':(uploadedAsset?'File uploaded successfully.':'Choose a WEBP image for this tab.')))}</div></div></article>`}
function renderOrderDetails(order){const brideRows=[['Bride Name',order.bride?.name],['Bride Parents',order.bride?.parents],['Bride Grandparents',order.bride?.grandparents]];if(order.bridePrefixSuffix)brideRows.push(['Prefix/Suffix Kept With Name?',`${order.bridePrefixSuffix.keepWithDisplayedName||'—'} (${order.bridePrefixSuffix.token||''})`]);const groomRows=[['Groom Name',order.groom?.name],['Groom Parents',order.groom?.parents],['Groom Grandparents',order.groom?.grandparents]];if(order.groomPrefixSuffix)groomRows.push(['Prefix/Suffix Kept With Name?',`${order.groomPrefixSuffix.keepWithDisplayedName||'—'} (${order.groomPrefixSuffix.token||''})`]);const closingRows=[['With Love Text',order.closing?.withLoveText],['Family Name',order.closing?.familyName]];if(order.religiousPreference)closingRows.push(['Religious Preference',order.religiousPreference]);const extraSections=[];if(order.caricatures?.wanted){const caricaturePhotos=(order.caricatures.photos||[]).map(p=>({fileName:p.fileName,url:p.url,originalName:p.originalName,caption:`Event ${p.event}`}));const bodyHtml=[field('Requested',order.caricatures.wanted?'Yes':'No'),field('Total Events',order.caricatures.totalEvents),field('Photos Required',order.caricatures.photosRequired),field('Additional Amount',order.caricatures.additionalAmount?`₹${order.caricatures.additionalAmount}`:''),photoGrid('Uploaded Photos',caricaturePhotos)].join('');extraSections.push(renderCollapseCustom('Personalized Event Caricatures',bodyHtml))}if(order.customization&&(order.customization.specialInstructions||(order.customization.photos||[]).length)){const customizationPhotos=(order.customization.photos||[]).map(p=>typeof p==='string'?{fileName:p,url:null}:{fileName:p.fileName,url:p.url,originalName:p.originalName});const bodyHtml=[field('Special Instructions',order.customization.specialInstructions),photoGrid('Uploaded Photos',customizationPhotos)].join('');extraSections.push(renderCollapseCustom('Fully Customized Invitation',bodyHtml))}return`<div class="grid">${renderCollapse('Customer Details',[['Person Placing Order',order.customer?.personPlacingOrder],['Email Address',order.customer?.emailAddress],['Phone Number',order.customer?.phoneNumber],['Invitation Side',order.customer?.invitationSide],['Which name should appear first?',order.customer?.nameOrder]],true)}${renderCollapse('Bride Details',brideRows)}${renderCollapse('Groom Details',groomRows)}${renderEventsCollapse(order.events)}${renderCollapse('Closing Details',closingRows)}${extraSections.join('')}</div>`}
function renderCollapse(title,rows,open=false){return`<details class="collapse" ${open?'open':''}><summary>${escapeHtml(title)}</summary><div class="collapse-body"><div class="grid">${rows.map(([k,v])=>field(k,v)).join('')}</div></div></details>`}
function renderCollapseCustom(title,bodyHtml,open=false){return`<details class="collapse" ${open?'open':''}><summary>${escapeHtml(title)}</summary><div class="collapse-body"><div class="grid">${bodyHtml}</div></div></details>`}
function photoGrid(label,items){if(!items||!items.length)return field(label,'');const thumbs=items.map(item=>{const caption=item.caption||item.fileName||item.originalName||'Photo';if(item.url){return`<article class="thumb-card"><button class="thumb-btn" type="button" data-preview-src="${escapeHtml(item.url)}" data-preview-title="${escapeHtml(caption)}"><img src="${escapeHtml(item.url)}" alt="${escapeHtml(caption)}" loading="lazy" /></button><div class="thumb-name">${escapeHtml(caption)}</div></article>`}return`<article class="thumb-card"><div class="thumb-name">${escapeHtml(caption)} (not uploaded)</div></article>`}).join('');return`<div class="card"><div class="k">${escapeHtml(label)}</div><div class="v"><div class="thumb-row" style="margin-top:6px;flex-wrap:wrap;">${thumbs}</div></div></div>`}
function renderEventsCollapse(events){return`<details class="collapse" open><summary>Events</summary><div class="collapse-body"><div class="grid">${events.length?events.map((ev,i)=>`<section class="glass" style="padding:12px;border-radius:16px;"><div class="k" style="margin-bottom:10px;">Event ${i+1}</div><div class="grid">${field('Event Name',ev.name)}${field('Event Date',ev.date)}${field('Event Time',ev.time)}${field('Venue',ev.venue)}${field('Google Maps Link',ev.googleMapsLink||ev.mapsLink)}</div></section>`).join(''):`<div class="card"><div class="v empty">Not provided</div></div>`}</div></div></details>`}
function field(k,v){return`<div class="card"><div class="k">${escapeHtml(k)}</div><div class="v ${v?'':'empty'}">${escapeHtml(v||'Not provided')}</div></div>`}
function renderModals(){const order=getSelectedOrder();if(state.modal.order&&order){el.orderModal.classList.remove('hidden');el.orderModal.classList.add('show');el.orderModalBody.innerHTML=renderOrderDetails(order)}else{el.orderModal.classList.add('hidden');el.orderModal.classList.remove('show');el.orderModalBody.innerHTML=''}if(state.modal.image&&state.modal.src){el.imageModal.classList.remove('hidden');el.imageModal.classList.add('show');el.imageModalTitle.textContent=state.modal.title||'Reference Preview';el.imageModalBody.innerHTML=`<div class="img-preview"><img src="${escapeHtml(state.modal.src)}" alt="${escapeHtml(state.modal.title||'Reference Preview')}" /></div>`}else{el.imageModal.classList.add('hidden');el.imageModal.classList.remove('show');el.imageModalBody.innerHTML=''}const clientOrder=getOrderById(state.modal.clientId);if(state.modal.client&&clientOrder){el.clientModal.classList.remove('hidden');el.clientModal.classList.add('show');el.clientModalBody.innerHTML=renderClientInfo(clientOrder)}else{el.clientModal.classList.add('hidden');el.clientModal.classList.remove('show');el.clientModalBody.innerHTML=''}const generationOrder=getOrderById(state.modal.generateId);if(state.modal.generate&&generationOrder){el.generationModal.classList.remove('hidden');el.generationModal.classList.add('show');el.generationModalBody.innerHTML=renderGenerationModal(generationOrder)}else{el.generationModal.classList.add('hidden');el.generationModal.classList.remove('show');el.generationModalBody.innerHTML=''}}
function renderClientInfo(order){return`<div class="client-grid"><div class="client-card"><div class="k">Name</div><div class="v">${escapeHtml(order.customer?.personPlacingOrder||order.customer?.name||'Not provided')}</div></div><div class="client-card"><div class="k">Phone Number</div><div class="v">${escapeHtml(order.customer?.phoneNumber||'Not provided')}</div></div><div class="client-card"><div class="k">Email Address</div><div class="v">${escapeHtml(order.customer?.emailAddress||'Not provided')}</div></div></div>`}
async function onWorkspaceClick(e){const a=e.target.closest('[data-approve]');if(a){await setStatus(a.dataset.approve,'Approved','approvedAt',false);return}const h=e.target.closest('[data-hold]');if(h){await setStatus(h.dataset.hold,'On Hold','heldAt',true);return}const r=e.target.closest('[data-reject]');if(r){await setStatus(r.dataset.reject,'Rejected','rejectedAt',true);return}const d=e.target.closest('[data-view-details]');if(d){state.modal.order=true;renderModals();return}const openGen=e.target.closest('[data-open-generate]');if(openGen){state.modal.generate=true;state.modal.generateId=openGen.dataset.openGenerate;renderModals();return}const cancelGen=e.target.closest('[data-cancel-generate]');if(cancelGen){closeGenerationModal();return}const confirmGen=e.target.closest('[data-confirm-generate]');if(confirmGen){closeGenerationModal();await runWebsiteGeneration(confirmGen.dataset.confirmGenerate);return}const uploadPrompt=e.target.closest('[data-upload-prompt-slot][data-slot]');if(uploadPrompt){const oid=uploadPrompt.dataset.uploadPromptSlot,slot=uploadPrompt.dataset.slot,file=state.uploads?.[oid]?.[slot]?.file;if(!file){alert('Choose a WEBP file first.');return}await queuePromptSlotUpload(oid,slot,file);return}const uploadSet=e.target.closest('[data-upload-website-assets]');if(uploadSet){await uploadWebsiteAssets(uploadSet.dataset.uploadWebsiteAssets,uploadSet.dataset.assetKey);return}const uploadMusicBtn=e.target.closest('[data-upload-music]');if(uploadMusicBtn){await uploadMusicAsset(uploadMusicBtn.dataset.uploadMusic);return}const saveMusicUrlBtn=e.target.closest('[data-save-music-url]');if(saveMusicUrlBtn){const oid=saveMusicUrlBtn.dataset.saveMusicUrl;const inputEl=(e.target.closest('[data-modal-body]')||document).querySelector('[data-music-url-input="'+oid+'"]');const pastedUrl=(inputEl?inputEl.value:'').trim();const startEl=document.querySelector('[data-music-start="'+oid+'"]');const endEl=document.querySelector('[data-music-end="'+oid+'"]');const musicStartSec=parseMusicSeconds(startEl?.value);const musicEndSec=parseMusicSeconds(endEl?.value);if(musicEndSec!==''&&musicEndSec<=((musicStartSec==='')?0:musicStartSec)){alert('End time must be greater than start time.');return}if(!pastedUrl){alert('Please paste a valid music URL.');return}const order=getOrderById(oid);if(!order)return;const next=getWebsiteGenerationData(order);next.assets={...next.assets,musicUrl:pastedUrl};next.musicStartSec=musicStartSec;next.musicEndSec=musicEndSec;next.updatedAt=new Date().toISOString();try{await updateDoc(doc(db,'orders',oid),{websiteGeneration:next})}catch(e2){console.warn('Firestore write failed:',e2)}mergeLocalWebsiteGeneration(oid,next);alert('Music URL saved.');renderWorkspace();renderModals();return}const copyBtn=e.target.closest('[data-copy-text]');if(copyBtn){await copyText(copyBtn.dataset.copyText||'');return}const openBtn=e.target.closest('[data-open-url]');if(openBtn){window.open(openBtn.dataset.openUrl,'_blank','noopener');return}const p=e.target.closest('[data-preview-src]');if(p){state.modal.image=true;state.modal.src=p.dataset.previewSrc;state.modal.title=p.dataset.previewTitle||'Reference Preview';renderModals()}}
async function setStatus(id,status,timeField,confirmFirst){try{if(confirmFirst&&!confirm(`Are you sure you want to mark this order as ${status}?`))return;state.busy[id]=true;renderWorkspace();await updateDoc(doc(db,'orders',id),{status,[timeField]:serverTimestamp()})}catch(err){console.error(err);alert(readableError(err))}finally{state.busy[id]=false;renderWorkspace()}}
function onWorkspaceChange(e){const t=e.target;if(t.matches('[data-order-upload][data-slot]')){const f=t.files?.[0];if(!f)return;if(!isWebp(f)){alert('Please upload WEBP only.');t.value='';return}const oid=t.dataset.orderUpload,slot=t.dataset.slot;state.uploads[oid]??={};if(state.uploads[oid][slot]?.url)URL.revokeObjectURL(state.uploads[oid][slot].url);state.uploads[oid][slot]={name:f.name,url:URL.createObjectURL(f),file:f};const ui=getWebsiteUi(oid);ui.uploads[slot]={...(ui.uploads[slot]||{}),busy:false,progress:0,error:'',success:''};renderWorkspace();renderModals();return}if(t.matches('[data-manual-ref][data-slot-index]')){const f=t.files?.[0];if(!f)return;const oid=t.dataset.manualRef,slot=Number(t.dataset.slotIndex);state.manualRefs[oid]??={};if(state.manualRefs[oid][slot]?.url)URL.revokeObjectURL(state.manualRefs[oid][slot].url);state.manualRefs[oid][slot]={name:f.name,url:URL.createObjectURL(f)};renderWorkspace();renderModals();return}if(t.matches('[data-add-more-images]')){const oid=t.dataset.addMoreImages;const files=[...(t.files||[])];if(!files.length)return;state.manualRefs[oid]??={};let next=Math.max(fixedImageSlotCount,...Object.keys(state.manualRefs[oid]).map(Number).filter(Number.isFinite),fixedImageSlotCount)+1;files.forEach(f=>{state.manualRefs[oid][next]={name:f.name,url:URL.createObjectURL(f)};next+=1});renderWorkspace();renderModals();t.value='';return}if(t.matches('[data-add-refs]')){[...(t.files||[])].forEach(f=>state.refs.template1.push({title:f.name,url:URL.createObjectURL(f),fixed:false}));renderWorkspace();return}if(t.matches('[data-website-files][data-asset-key]')){const oid=t.dataset.websiteFiles,key=t.dataset.assetKey,ui=getWebsiteUi(oid),files=[...(t.files||[])];ui.drafts[key]=files.map(file=>({file,name:file.name}));ui.uploads[key]={...(ui.uploads[key]||{}),error:'',success:'',progress:0,busy:false};renderWorkspace();renderModals();}if(t.matches('[data-music-file]')){const oid=t.dataset.musicFile,file=t.files?.[0];if(!file)return;const ui=getWebsiteUi(oid);ui.musicDraft={file,name:file.name};ui.musicUpload={busy:false,progress:0,error:'',success:''};renderWorkspace();renderModals();}if(t.matches('[data-music-mode]')){const oid=t.dataset.musicMode,ui=getWebsiteUi(oid);ui.musicMode=t.value;renderWorkspace();renderModals();return}if(t.matches('[data-music-start]')){const oid=t.dataset.musicStart,ui=getWebsiteUi(oid);ui.musicClip={...(ui.musicClip||{}),start:t.value};return}if(t.matches('[data-music-end]')){const oid=t.dataset.musicEnd,ui=getWebsiteUi(oid);ui.musicClip={...(ui.musicClip||{}),end:t.value};return}}
function closeOrderModal(){state.modal.order=false;renderModals()}
function closeImageModal(){state.modal.image=false;state.modal.src='';state.modal.title='';renderModals()}
function closeClientModal(){state.modal.client=false;state.modal.clientId=null;renderModals()}
function closeGenerationModal(){state.modal.generate=false;state.modal.generateId=null;renderModals()}
