function renderInvitationHtml(model){let html=String(WEBSITE_TEMPLATE||'');Object.entries(model).forEach(([k,v])=>{html=html.split(`{{${k}}}`).join(String(v??''))});return html.replace(/\{\{[^}]+\}\}/g,'')}
function buildEventsHtml(events){return(events||[]).filter(ev=>assetUrl(ev?.imageUrl||ev)).map((ev,i)=>`<div class="event-card"><img src="${escapeHtml(assetUrl(ev.imageUrl||ev))}" alt="${escapeHtml(ev?.name||`Event schedule card ${i+1}`)}" / decoding="async"></div>`).join('')}
function buildVenuesHtml(events){return(events||[]).map((ev,i)=>{const venue=String(ev?.venue||'').trim(),mapUrl=extractMapUrl(ev);if(!venue&&!mapUrl)return'';let html=`<p class="venue-address"${i>0?' style="margin-top:30px"':''}>${escapeHtmlMultiline(venue||String(ev?.name||'Venue').trim())}</p>`;if(mapUrl){html+=`<div class="map-frame"><iframe title="${escapeHtml((String(ev?.name||'Venue').trim()||'Venue')+' map')}" loading="lazy" referrerpolicy="no-referrer-when-downgrade" src="${escapeHtml(buildGoogleMapsEmbedUrl(mapUrl,venue||ev?.name||''))}"></iframe></div>`;html+=`<a class="map-link" href="${escapeHtml(mapUrl)}" target="_blank" rel="noopener">Open location in Google Maps</a>`}return html}).filter(Boolean).join('')}
function buildGalleryHtml(images){return''}
function extractMapUrl(ev){return String(ev?.googleMapsLink||ev?.mapsLink||ev?.mapUrl||ev?.map||ev?.maps||ev?.locationUrl||'').trim()}
function buildGoogleMapsEmbedUrl(mapUrl,venue){const raw=String(mapUrl||'').trim();const place=String(venue||'').trim();if(/output=embed/i.test(raw))return raw;try{const u=new URL(raw);const q=u.searchParams.get('q')||u.searchParams.get('query')||u.searchParams.get('destination')||u.searchParams.get('daddr')||u.searchParams.get('ll');if(q)return `https://www.google.com/maps?q=${encodeURIComponent(q)}&output=embed`;if(/google\.[^/]+\/maps/.test(u.href))return `https://www.google.com/maps?q=${encodeURIComponent(place||u.href)}&output=embed`}catch{}return `https://www.google.com/maps?q=${encodeURIComponent(place||raw)}&output=embed`}
function buildRevealDateIso(value){const p=parseLooseDateParts(value);if(!p)return'';const pad=n=>String(n).padStart(2,'0');return `${p.year}-${pad(p.month)}-${pad(p.day)}T00:00:00`}
function buildPresenceHtml(order,ordered){const explicit=String(order.closing?.withLoveText||'').trim();if(explicit)return escapeHtmlMultiline(explicit);const people=[];ordered.forEach(person=>{if(person?.parents)people.push(person.parents);if(person?.grandparents)people.push(person.grandparents)});if(people.length)return people.map(v=>escapeHtmlMultiline(String(v||'').trim())).filter(Boolean).join('<br/>');return escapeHtmlMultiline(ordered.map(v=>String(v?.name||'').trim()).filter(Boolean).join(' & '))}
function escapeHtmlMultiline(v){const nl=String.fromCharCode(10),cr=String.fromCharCode(13);return escapeHtml(String(v??'')).split(cr+nl).join(nl).split(cr).join(nl).split(nl).join('<br/>')}
function findWeddingEvent(events){const list=Array.isArray(events)?events:[];return list.find(ev=>/wedding|shaadi|shadi|nikah|phere|lagna|vivah/i.test(String(ev?.name||'')))||list[0]||null}
function monthName(i){return['January','February','March','April','May','June','July','August','September','October','November','December'][i]||''}
function parseLooseDateParts(value){const raw=String(value||'').trim();if(!raw)return null;let m=raw.match(/(\d{4})-(\d{1,2})-(\d{1,2})/);if(m)return{year:+m[1],month:+m[2],day:+m[3]};m=raw.match(/(\d{1,2})[\/-](\d{1,2})[\/-](\d{2,4})/);if(m){let a=+m[1],b=+m[2],c=+m[3];if(c<100)c+=2000;const day=a>12?a:b,month=a>12?b:a;return{year:c,month,day}}const d=new Date(raw);if(!Number.isNaN(d.getTime()))return{year:d.getFullYear(),month:d.getMonth()+1,day:d.getDate()};return null}
function formatRevealDateText(value){const p=parseLooseDateParts(value);if(!p)return String(value||'Date to be announced');return `${p.day} ${monthName(p.month-1)} ${p.year}`}
function buildFamilyName(order,ordered){const explicit=String(order.closing?.familyName||'').trim();if(explicit)return explicit;const names=ordered.map(v=>String(v?.name||'').trim()).filter(Boolean);return names.length?`${names.join(' & ')} Family`:''}
function buildPresenceText(order,ordered){const explicit=String(order.closing?.withLoveText||'').trim();if(explicit)return explicit.split('\n').join('<br/>');const people=[];ordered.forEach(person=>{if(person?.parents)people.push(person.parents);if(person?.grandparents)people.push(person.grandparents)});if(people.length)return people.map(v=>String(v||'').trim()).filter(Boolean).join('<br/>');return ordered.map(v=>String(v?.name||'').trim()).filter(Boolean).join(' & ')}
function normalizeWorkerAssets(items,prefix){return(items||[]).map((item,index)=>typeof item==='string'?{name:`${prefix}${index+1}`,rawUrl:item,url:item}:item).map(item=>({name:item.name||item.fileName||'',rawUrl:item.rawUrl||item.url||item.downloadUrl||'',url:item.rawUrl||item.url||item.downloadUrl||'',contentType:item.contentType||'',size:item.size||0})).filter(item=>item.rawUrl)}
function buildShortAssetName(prefix,index,fileName){const cleanExt=((String(fileName).match(/\.[a-z0-9]+$/i)||[''])[0]||'').toLowerCase()||'.bin';return `${prefix}${index+1}${cleanExt}`}
function composeWebsiteUrl(folderSlug){return ensureTrailingSlash(`${WEBSITE_PIPELINE_CONFIG.websiteBaseUrl.replace(/\/$/,'')}/${folderSlug}`)}
function composeAlterationUrl(folderSlug){return ensureTrailingSlash(`${WEBSITE_PIPELINE_CONFIG.alterationBaseUrl.replace(/\/$/,'')}/${folderSlug}`)}
function buildFolderSlug(order){const ordered=getOrderedPeople(order).map(v=>slugifyName(v?.name||'')).filter(Boolean);return ordered.length?ordered.join('-'):slugifyName(order.orderId||'invitation')}
function findAssetUrl(items,keywords){const list=(items||[]).map(v=>({url:assetUrl(v),name:assetName(v).toLowerCase()})).filter(v=>v.url);for(const key of keywords){const found=list.find(v=>v.name.includes(String(key).toLowerCase()));if(found)return found.url}return''}
function firstAssetUrl(items){return assetUrl((items||[])[0]||'')}
function nthAssetUrl(items,index){return assetUrl((items||[])[index]||'')}
function assetUrl(item){return typeof item==='string'?item:(item?.rawUrl||item?.url||item?.downloadUrl||'')}
function assetName(item){return typeof item==='string'?item:(item?.name||item?.fileName||'')}
function findAudioUrl(items){return(items||[]).map(v=>assetUrl(v)).find(v=>/\.(mp3|wav|m4a|aac|ogg)(\?|$)/i.test(v||''))||''}
function parseMusicSeconds(value){const raw=String(value??'').trim().toLowerCase();if(!raw)return'';const cleaned=raw.replace(/(\d+(?:\.\d+)?)(?:st|nd|rd|th)\b/g,'$1');if(/^\d+:\d{1,2}$/.test(cleaned)){const[m,s]=cleaned.split(':').map(Number);return(m*60)+s}const minuteMatch=cleaned.match(/^(\d+(?:\.\d+)?)\s*(m|min|mins|minute|minutes)$/);if(minuteMatch)return Math.round(parseFloat(minuteMatch[1])*60);const secondMatch=cleaned.match(/^(\d+(?:\.\d+)?)\s*(s|sec|secs|second|seconds)?$/);if(secondMatch)return Math.round(parseFloat(secondMatch[1]));return''}
function slugifyName(v){return String(v||'').normalize('NFKD').replace(/[^\w\s-]/g,'').trim().replace(/\s+/g,'-').replace(/-+/g,'-')||'invitation'}
function ensureTrailingSlash(v){return String(v||'').replace(/\/+$/,'')+'/'}
function readableGenerationError(err){return err?.message||'Website generation failed. Please verify worker configuration and uploaded assets.'}
function formatDuration(ms){const s=Math.max(1,Math.round(ms/1000));return s<60?`${s}s`:`${Math.floor(s/60)}m ${s%60}s`}
function formatIso(v){if(!v)return'—';const d=new Date(v);return Number.isNaN(d.getTime())?String(v):new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(d)}
async function copyText(text){try{await navigator.clipboard.writeText(String(text||''));alert('Copied to clipboard.')}catch{alert('Copy failed.')}}
async function waitForPublish(seed){if(seed?.jobId){const start=Date.now();while(Date.now()-start<WEBSITE_PIPELINE_CONFIG.pollTimeoutMs){await delay(WEBSITE_PIPELINE_CONFIG.pollIntervalMs);const res=await fetch(`${WEBSITE_PIPELINE_CONFIG.workerUrl}?action=publish-status&jobId=${encodeURIComponent(seed.jobId)}`).then(r=>r.json());if(res.status==='success'||res.ready===true)return {...seed,...res};if(res.status==='error')throw new Error(res.message||'Publishing failed.')}}return seed}
async function postJson(url,payload){const res=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});if(!res.ok)throw new Error(`Request failed with status ${res.status}`);return await res.json()}
function xhrUploadFlexible(url,formData,onProgress){return new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',url,true);xhr.upload.onprogress=e=>{if(e.lengthComputable&&onProgress)onProgress(Math.round((e.loaded/e.total)*100))};xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300){const body=(xhr.responseText||'').trim();try{resolve(JSON.parse(body))}catch{resolve({rawText:body,rawUrl:/^https?:\/\//i.test(body)?body:''})}}else reject(new Error(`Upload failed (${xhr.status}) ${xhr.responseText||''}`.trim()))};xhr.onerror=()=>reject(new Error('Network error while uploading.'));xhr.send(formData)})}
function extractUploadedUrl(res){if(!res)return'';if(typeof res==='string'){return /^https?:\/\//i.test(res)?res:''}if(res.rawUrl)return res.rawUrl;if(res.url)return res.url;if(res.downloadUrl)return res.downloadUrl;if(res.raw_url)return res.raw_url;if(res.raw)return res.raw;if(Array.isArray(res.uploaded)&&res.uploaded[0]){const v=res.uploaded[0];return typeof v==='string'?v:(v.rawUrl||v.url||'')}if(Array.isArray(res.assets)&&res.assets[0]){const v=res.assets[0];return typeof v==='string'?v:(v.rawUrl||v.url||'')}if(res.data){return extractUploadedUrl(res.data)}return''}
async function xhrUploadJson(url,formData,onProgress){return await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST',url,true);xhr.upload.onprogress=e=>{if(e.lengthComputable&&onProgress)onProgress(Math.round((e.loaded/e.total)*100))};xhr.onload=()=>{if(xhr.status>=200&&xhr.status<300){try{resolve(JSON.parse(xhr.responseText||'{}'))}catch(err){reject(err)}}else reject(new Error(`Upload failed with status ${xhr.status}`))};xhr.onerror=()=>reject(new Error('Upload request failed.'));xhr.send(formData)})}
function delay(ms){return new Promise(r=>setTimeout(r,ms))}

function markRead(id){state.read[id]=true;localStorage.setItem(readKey,JSON.stringify(state.read))}
function getSelectedOrder(){return state.filtered.find(v=>v.docId===state.selected)||null}
function resolveTemplateKey(templateId){return Object.values(TEMPLATE_LIBRARY.templates).find(t=>t.supportedTemplateIds.includes(templateId))?.key||TEMPLATE_LIBRARY.defaultTemplateKey}
function getOrderedPeople(order){const b={name:order.bride?.name||'',parents:order.bride?.parents||'',grandparents:order.bride?.grandparents||''},g={name:order.groom?.name||'',parents:order.groom?.parents||'',grandparents:order.groom?.grandparents||''};return String(order.customer?.nameOrder||'').toLowerCase().includes('groom')?[g,b]:[b,g]}
function getOrderedInitials(order){const b=getInitial(order.bride?.name),g=getInitial(order.groom?.name);return String(order.customer?.nameOrder||'').toLowerCase().includes('groom')?`${g}${b}`:`${b}${g}`}
function getInitial(v){const t=String(v||'').trim();if(!t)return'X';const m=t.match(/[A-Za-z0-9]/);return(m?m[0]:t[0]).toUpperCase()}
function formatEventInfo(ev){return[ev?.name||'',ev?.date||'',ev?.time||'',ev?.venue||''].filter(Boolean).join('\n')}
function normalizeStatus(v){return String(v||'waiting').trim().toLowerCase().replace(/\s+/g,'-')}
function readableError(err){const c=err?.code||'';if(c.includes('permission-denied'))return'Firebase rules are blocking this action.';if(c.includes('unavailable'))return'Network connection is unavailable right now.';return'Something went wrong while connecting to Firebase.'}
function toMillis(ts){try{if(!ts)return 0;if(typeof ts.toDate==='function')return ts.toDate().getTime();return new Date(ts).getTime()||0}catch{return 0}}
function formatDate(ts){const ms=toMillis(ts);if(!ms)return'No date';return new Intl.DateTimeFormat(undefined,{dateStyle:'medium',timeStyle:'short'}).format(new Date(ms))}
function toDateFilterValue(ts){const ms=toMillis(ts);if(!ms)return'';const d=new Date(ms),pad=n=>String(n).padStart(2,'0');return`${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`}
function isWebp(file){return file.type==='image/webp'||String(file.name||'').toLowerCase().endsWith('.webp')}
function safeId(v){return String(v||'').replace(/[^a-zA-Z0-9_-]/g,'_')}
function escapeHtml(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
